import { test, expect } from '@playwright/test';

test.describe('Virtual Scroll List Performance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should render the virtual scroll list without lag', async ({ page }) => {
    const list = page.getByRole('list', { name: 'Virtual Scroll List' });
    await expect(list).toBeVisible();

    const initialRowCount = await list.locator('li').count();
    expect(initialRowCount).toBeLessThanOrEqual(100); // Assuming initial load shows 100 rows

    await page.mouse.wheel(0, 1000); // Scroll down
    await page.waitForTimeout(1000); // Wait for loading new rows

    const newRowCount = await list.locator('li').count();
    expect(newRowCount).toBeGreaterThan(initialRowCount);
  });

  test('should handle scrolling to the bottom without performance issues', async ({ page }) => {
    const list = page.getByRole('list', { name: 'Virtual Scroll List' });
    await expect(list).toBeVisible();

    await page.mouse.wheel(0, 10000); // Scroll to the bottom
    await page.waitForTimeout(1000); // Wait for loading new rows

    const finalRowCount = await list.locator('li').count();
    expect(finalRowCount).toBe(10000); // Assuming all rows are loaded
  });
});
